/* @lc app=leetcode id=2642 lang=kotlin */
class Graph(val n: Int, edges: Array<IntArray>) { val adj = Array(n) { mutableListOf<Pair<Int, Int>>() }.also { a -> edges.forEach { e -> a[e[0]].add(e[1] to e[2]) } } fun addEdge(edge: IntArray): Unit = adj[edge[0]].add(edge[1] to edge[2]).let { } fun shortestPath(node1: Int, node2: Int): Int = IntArray(n) { 1e9.toInt() }.also { d -> d[node1] = 0 }.let { dist -> java.util.PriorityQueue<Pair<Int, Int>>(compareBy { it.second }).apply { add(node1 to 0) }.let { pq -> generateSequence { if (pq.isNotEmpty()) pq.poll() else null }.firstOrNull { (u, d) -> u == node2 || (d <= dist[u]).let { valid -> if (valid) adj[u].forEach { (v, w) -> if (d + w < dist[v]) dist.set(v, d + w).also { pq.add(v to d + w) } } false } }?.second ?: -1 } } }